sys_variable_value.value:
(function execute(inputs, outputs) {
  var propriedade = [
    "sn_disco_certmgmt.BNB_instalacao_certificados",
    "sn_disco_certmgmt.BNB_certificados_externos",
    "sn_disco_certmgmt.BNB_certificados_internos"
  ];

  var nomeDeGrupos = {
    instalacao_de_certificados: gs.getProperty(propriedade[0]),
    certificados_externos: gs.getProperty(propriedade[1]),
    certificados_internos: gs.getProperty(propriedade[2])
  };
  for (var nome in nomeDeGrupos) {
    var nomeGrupo = nomeDeGrupos[nome];
    if (!nomeGrupo) {
      throw new Error("Essas propriedades devem ser configuradas com os nomes dos grupos correspondentes: " + propriedade.join(", "));
    }
    var grupo = new global.GlideQuery("sys_user_group")
      .where("name", nomeGrupo)
      .selectOne("sys_id", "name")
      .orElse({ sys_id: null });
    outputs[nome] = grupo.sys_id;
    gs.info(nomeGrupo + '- ' + nome + ' - ' + grupo.name);
  }

})(inputs, outputs);

